const OCS_BASE = 'https://your-ocs-server.example.com/ocsapi/v1';
const AUTH = 'Basic ' + Buffer.from('CHANGE_ME_USER:CHANGE_ME_PASSWORD').toString('base64');

// ─── helpers ─────────────────────────────────────────────
const VIRTUAL_MAC_PREFIXES = ['00:09:0F','00:15:5D','00:50:56','00:0C:29','00:1C:42','52:54:00','08:00:27','00:00:00','FF:FF:FF'];
const GENERIC_SERIALS = ['to be filled by o.e.m.','to be filled by oem','default string','system serial number','not specified','not applicable','none','o.e.m.','oem','serial','0123456789','gigabyte technology co., ltd.','microsoft corporation','hpe','asus','asustek computer inc.','dell inc.','lenovo','hp'];
function cleanSerial(s){if(!s)return'';s=String(s).trim();if(s.length<4)return'';const l=s.toLowerCase();for(const b of GENERIC_SERIALS)if(l.includes(b))return'';return s;}
function isVirtualMac(m){if(!m)return true;const u=m.toUpperCase();return VIRTUAL_MAC_PREFIXES.some(p=>u.startsWith(p));}
function pickMac(nets){const c=(nets||[]).filter(n=>n.MACADDR && !isVirtualMac(n.MACADDR));const up=c.find(n=>n.STATUS==='Up' && n.IPADDRESS && !n.IPADDRESS.startsWith('127'));if(up)return up.MACADDR.toUpperCase();const u=c.find(n=>n.STATUS==='Up');if(u)return u.MACADDR.toUpperCase();if(c.length)return c[0].MACADDR.toUpperCase();return null;}
function pickIp(nets){const up=(nets||[]).find(n=>n.STATUS==='Up' && n.IPADDRESS && !n.IPADDRESS.startsWith('127'));if(up)return up.IPADDRESS;const a=(nets||[]).find(n=>n.IPADDRESS && !n.IPADDRESS.startsWith('127') && n.IPADDRESS!=='0.0.0.0');return a?a.IPADDRESS:null;}
function pickSerial(b){if(!b||!b.length)return null;const x=b[0];return cleanSerial(x.SSN) || cleanSerial(x.MSN) || cleanSerial(x.ASSETTAG) || null;}
function parseSmartTipo(s){if(!s)return null;const t=String(s).toUpperCase();if(t.includes('SSD')||t.includes('SOLID')||t.includes('NVME')||t.includes('M.2'))return'SSD';if(t.includes('RPM') && !t.includes('---'))return'HDD';if(t.includes('----'))return'SSD';return null;}
function parseSmartEstado(s){if(!s)return null;return String(s).replace(/^[^:]+:\s*/,'').trim();}
function parseSmartHoras(s){if(!s)return null;const m=String(s).match(/(\d+)/);return m?parseInt(m[1],10):null;}
const SSD_PATTERNS=[/\bSSD\b/i,/SOLID\s*STATE/i,/\bNVME\b/i,/\bM\.?2\b/i,/\bWDS\d/i,/\bWD_BLACK\s*SN/i,/\bMZ-[VN]/i,/\bMZ-?7/i,/\b860\s*EVO\b/i,/\b870\s*EVO\b/i,/\b980\b/i,/\b990\b/i,/\b850\s*PRO\b/i,/\bCT\d+[MP]X/i,/\bSA400\b/i,/\bKC\d/i,/\bSUV\d/i,/\bSSDPE/i,/\bSSDSC/i,/\bSN[0-9]{3,}/i,/\bP[1-9]\s*\b/i,/\bKINGSTON/i];
const HDD_PATTERNS=[/\bWD[CRD]?\s*WD\b/i,/\bST\d{3,}/i,/\bHGST/i,/\bHITACHI/i,/\bMAXTOR/i,/\bBARRACUDA/i];
function diskTypeFromModel(m){if(!m)return null;for(const p of SSD_PATTERNS)if(p.test(m))return'SSD';for(const p of HDD_PATTERNS)if(p.test(m))return'HDD';return null;}
function kbStats(sw,now){now=now||new Date();let last=null,c30=0;const cut=now.getTime()-30*24*3600*1000;const isKb=s=>/\bKB\d{5,}/i.test(String(s.NAME||''));for(const s of (sw||[])){if(!isKb(s))continue;const dStr=s.INSTALLDATE;if(!dStr||dStr.startsWith('0000'))continue;const d=new Date(dStr);if(isNaN(d.getTime()))continue;if(!last||d>last)last=d;if(d.getTime()>=cut)c30++;}return{lastKb:last?last.toISOString():null,count30d:c30};}
function isVirtualHost(b){if(!b||!b.length)return false;const x=b[0];const blob=`${x.BMANUFACTURER||''} ${x.SMANUFACTURER||''} ${x.SMODEL||''} ${x.MMANUFACTURER||''}`.toLowerCase();return['hyper-v','vmware','virtualbox','qemu','kvm','xen','virtual machine','parallels'].some(t=>blob.includes(t));}
function parseUptime(u){if(!u)return null;if(Array.isArray(u) && u.length)u=u[0].DURATION;if(!u)return null;if(typeof u==='string'){const d=u.match(/(\d+)\s*d/i);if(d)return parseInt(d[1],10);}return null;}

function parseComputer(c){
  const hw=c.hardware||{};const cpus=c.cpus||[];const mems=c.memories||[];const nets=c.networks||[];
  const stor=c.storages||[];const ai=c.accountinfo||[];const bios=c.bios||[];const drives=c.drives||[];
  const smart=c.smartsti||[];const softs=c.softwares||[];
  const ocs_id=parseInt(hw.ID||0,10);if(!ocs_id)return null;
  const workgroup=((ai.find(a=>a.TAG)||{}).TAG||'').toString().toUpperCase();
  const total_cores=cpus.reduce((s,cpu)=>s+Math.max(parseInt(cpu.CORES||0,10),parseInt(cpu.LOGICAL_CPUS||0,10),1),0);
  const cpu_name=(cpus[0] && cpus[0].TYPE)||'';
  const cpu_speed=cpus[0]?parseInt(cpus[0].SPEED||0,10):0;
  const ram_mb=mems.reduce((s,m)=>s+parseInt(m.CAPACITY||0,10),0);
  const ip=pickIp(nets);const mac=pickMac(nets);const bios_serial=pickSerial(bios);
  const disks=stor.filter(s=>!String(s.TYPE||'').toLowerCase().includes('removable') && parseInt(s.DISKSIZE||0,10)>100)
                  .sort((a,b)=>parseInt(b.DISKSIZE||0,10)-parseInt(a.DISKSIZE||0,10));
  const primary=disks[0]||{};
  const disk_gb=primary.DISKSIZE?Math.round(parseInt(primary.DISKSIZE,10)/1024):0;
  const disk_model=`${primary.MODEL||''} ${primary.NAME||''} ${primary.DESCRIPTION||''}`.trim();
  let disk_type=null;
  if(smart.length)disk_type=parseSmartTipo(smart[0].TIPO);
  if(!disk_type)disk_type=diskTypeFromModel(disk_model);
  const disk_health=smart.length?parseSmartEstado(smart[0].ESTADO):null;
  const disk_hours_on=smart.length?parseSmartHoras(smart[0].HORAS):null;
  let disk_used_pct=null;
  const cDrive=drives.find(d=>String(d.LETTER||'').toUpperCase().startsWith('C:'));
  if(cDrive && cDrive.TOTAL && cDrive.FREE!=null){
    const t=parseInt(cDrive.TOTAL,10),f=parseInt(cDrive.FREE,10);
    if(t>0)disk_used_pct=Math.round(((t-f)/t)*100);
  }
  const kb=kbStats(softs);
  const is_virtual=isVirtualHost(bios);
  let last_contact=null;
  if(hw.LASTDATE){try{const d=new Date(String(hw.LASTDATE).replace('T',' '));if(!isNaN(d.getTime()))last_contact=d.toISOString();}catch(_){}}
  const uptime_days=parseUptime(c.uptime);
  const hardware_uuid=String(hw.UUID||'').trim()||null;

  // ─── arrays detalladas (JSONB) ─────────────────────────
  // smart map: relacionar smart con disk por MODELO (mejor effort)
  function smartForDisk(d){
    if(!smart.length) return null;
    const dModel = String(d.MODEL||'').toLowerCase();
    const dName = String(d.NAME||'').toLowerCase();
    const s = smart.find(sm => {
      const m = String(sm.MODELO||'').toLowerCase();
      return m && (dModel.includes(m) || m.includes(dModel) || dName.includes(m) || m.includes(dName));
    }) || smart[0];
    if(!s) return null;
    const tempM = String(s.TEMPERATURA||'').match(/(\d+)/);
    return {
      status: parseSmartEstado(s.ESTADO),
      hours: parseSmartHoras(s.HORAS),
      temperatureC: tempM ? parseInt(tempM[1],10) : null,
    };
  }
  const disks_json = (stor||[])
    .filter(s => parseInt(s.DISKSIZE||0,10) > 100)
    .map(s => {
      const m = `${s.MODEL||''} ${s.NAME||''} ${s.DESCRIPTION||''}`.trim();
      let t = parseSmartTipo(s.TYPE);
      if(!t) t = diskTypeFromModel(m);
      return {
        model: m || null,
        name: s.NAME || null,
        manufacturer: s.MANUFACTURER || null,
        firmware: s.FIRMWARE || null,
        serial: cleanSerial(s.SERIALNUMBER) || null,
        type: t,
        sizeMb: parseInt(s.DISKSIZE||0,10) || null,
        smart: smartForDisk(s),
      };
    });

  const memory_slots_json = (mems||[])
    .filter(m => parseInt(m.CAPACITY||0,10) > 0)
    .map(m => ({
      slot: m.NUMSLOTS != null ? String(m.NUMSLOTS) : (m.CAPTION || null),
      capacityMb: parseInt(m.CAPACITY||0,10) || null,
      speed: m.SPEED || null,
      type: m.TYPE || null,
      caption: m.CAPTION || null,
    }));

  const networks_json = (nets||[])
    .filter(n => n.MACADDR)
    .map(n => ({
      name: n.DESCRIPTION || null,
      mac: String(n.MACADDR||'').toUpperCase(),
      ip: n.IPADDRESS || null,
      gateway: n.IPGATEWAY || null,
      mask: n.IPMASK || null,
      dhcp: n.DHCP || null,
      speed: n.SPEED || null,
      status: n.STATUS || null,
      isVirtual: isVirtualMac(n.MACADDR),
      type: n.TYPE || null,
    }));

  const drives_json = (drives||[])
    .filter(d => d.LETTER && parseInt(d.TOTAL||0,10) > 0)
    .map(d => {
      const t = parseInt(d.TOTAL||0,10);
      const f = parseInt(d.FREE||0,10);
      return {
        letter: d.LETTER,
        totalMb: t || null,
        freeMb: f || null,
        usedPct: t > 0 ? Math.round(((t - f) / t) * 100) : null,
        filesystem: d.FILESYSTEM || null,
        volume: d.VOLUMN || null,
        type: d.TYPE || null,
      };
    });

  return {
    ocs_id, workgroup, name:String(hw.NAME||''),
    os:String(hw.OSNAME||''), os_version:String(hw.OSVERSION||''),
    cpu:cpu_name, cpu_cores:total_cores, cpu_speed_mhz:cpu_speed, ram_mb,
    disk_gb, disk_type, ip, mac, bios_serial,
    last_contact, username:String(hw.LASTLOGGEDUSER || hw.USERID || ''),
    disk_used_pct, disk_health, disk_hours_on,
    last_kb_update:kb.lastKb, kb_count_30d:kb.count30d,
    is_virtual, uptime_days, hardware_uuid,
    disks_json: JSON.stringify(disks_json),
    memory_slots_json: JSON.stringify(memory_slots_json),
    networks_json: JSON.stringify(networks_json),
    drives_json: JSON.stringify(drives_json),
  };
}

// ─── fetch paginated ─────────────────────────────────────
const PAGE_SIZE = 100;
let allItems = [];
let start = 0;
let pageCount = 0;
const startedAt = Date.now();

while (true) {
  const url = `${OCS_BASE}/computers?start=${start}&limit=${PAGE_SIZE}`;
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: { Authorization: AUTH },
    skipSslCertificateValidation: true,
    json: true,
    timeout: 60000,
  });
  if (!resp || typeof resp !== 'object') break;
  const entries = Object.values(resp);
  if (!entries.length) break;
  for (const c of entries) {
    const parsed = parseComputer(c);
    if (parsed) allItems.push({ json: parsed });
  }
  pageCount++;
  if (entries.length < PAGE_SIZE) break;
  start += PAGE_SIZE;
  if (pageCount > 100) break; // safety
}

return [{ json: { rows: allItems.map(i => i.json) } }];
